                        seen.add((yy, xx))
                        q.append((yy, xx))
            if col != 6 and len(cells) > 1:
                comps.append((col, cells))

    def shape(cells):
        my, mx = min(y for y, x in cells), min(x for y, x in cells)
        return frozenset((y-my, x-mx) for y, x in cells)

    # Recolor the member of an identical-shape pair that is not the
    # background, using the color of the long straight marker.
    marker = None
    for col, cells in comps:
        ys = [y for y, x in cells]
        xs = [x for y, x in cells]
        if (len(set(xs)) == 1 or len(set(ys)) == 1) and len(cells) >= 5:
            marker = col
            break
    if marker is None:
        return [row[:] for row in grid]

    groups = defaultdict(list)
    for col, cells in comps:
        groups[shape(cells)].append((col, cells))
    out = [row[:] for row in grid]
    for group in groups.values():
        if len(group) >= 2:
            # Usually the repeated object on the opposite side of the marker
            # is the one that takes the marker color.
            for col, cells in group:
